-- agent-auth: the whole schema (PostgreSQL 16+).
--
-- Conventions:
-- * ids are uuid (generated by the application), timestamps timestamptz
--   (UTC), JSON jsonb unless the exact text must come back (a2a payloads).
-- * enumerations are text with a CHECK (the Rust side parses them at the
--   boundary; a value outside the list is refused by the database too).
-- * invariants the specs state are encoded here as well as in the types:
--   CHECKs tie nullable columns together, composite foreign keys tie a row
--   to the right agent, and triggers refuse status changes the state
--   machines do not allow. The Rust code is the first line; this is the
--   backstop for anything that reaches the database another way.
-- * lengths: the specs' varchar limits are CHECKs on text, so a too-long
--   value is a clear constraint error rather than a silent truncation, and
--   values whose length is validated by the application (redirect URIs,
--   URLs) are plain text.

-- ------------------------------------------------------------- daemons

CREATE TABLE daemons (
    id           uuid PRIMARY KEY,
    role         text NOT NULL CHECK (role IN ('host', 'sandbox')),
    name         text NOT NULL CHECK (name ~ '^[a-z0-9][a-z0-9-]{0,62}$'),
    public_key   text NOT NULL CHECK (length(public_key) BETWEEN 1 AND 128),
    paired_at    timestamptz NOT NULL,
    last_seen_at timestamptz,
    version      text CHECK (version ~ '^[0-9A-Za-z.+_-]{1,64}$'),
    -- Daemon-reported; informational only, never an authorization input.
    last_status  jsonb CHECK (last_status IS NULL OR jsonb_typeof(last_status) = 'object'),
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_daemons_role_name UNIQUE (role, name)
);

CREATE TABLE daemon_pairing_codes (
    id              uuid PRIMARY KEY,
    role            text NOT NULL CHECK (role IN ('host', 'sandbox')),
    name            text NOT NULL CHECK (name ~ '^[a-z0-9][a-z0-9-]{0,62}$'),
    -- The HMAC key derived from the code (hex); the code itself is never stored.
    pairing_key     text NOT NULL CHECK (pairing_key ~ '^[0-9a-f]{64}$'),
    expires_at      timestamptz NOT NULL,
    used_at         timestamptz,
    failed_attempts integer NOT NULL DEFAULT 0 CHECK (failed_attempts >= 0),
    created_at      timestamptz NOT NULL DEFAULT now(),
    updated_at      timestamptz NOT NULL DEFAULT now()
);
-- Only the newest code for a daemon is live: issuing one burns the others,
-- and the database refuses two unused codes for one (role, name).
CREATE UNIQUE INDEX uq_daemon_pairing_codes_live
    ON daemon_pairing_codes (role, name) WHERE used_at IS NULL;
CREATE INDEX ix_daemon_pairing_codes_role_name
    ON daemon_pairing_codes (role, name, created_at DESC);

-- -------------------------------------------------------------- agents

CREATE TABLE agents (
    id                       uuid PRIMARY KEY,
    name                     text NOT NULL UNIQUE CHECK (name ~ '^[a-zA-Z0-9._-]{1,128}$'),
    description              text NOT NULL DEFAULT '',
    key_id                   text NOT NULL UNIQUE CHECK (length(key_id) BETWEEN 1 AND 16),
    -- sha256 hex of the key's secret ('!' x 64 for the operator: matches nothing).
    api_key_hash             text NOT NULL CHECK (length(api_key_hash) = 64),
    webhook_url              text,
    webhook_secret           text CHECK (length(webhook_secret) <= 64),
    lldap_username           text CHECK (length(lldap_username) <= 128),
    lldap_password_encrypted text,
    disabled                 boolean NOT NULL DEFAULT false,
    kind                     text NOT NULL DEFAULT 'service'
                             CHECK (kind IN ('service', 'ephemeral', 'operator')),
    last_seen_at             timestamptz,
    last_listen_at           timestamptz,
    parent_agent_id          uuid REFERENCES agents (id),
    sandbox_id               uuid REFERENCES daemons (id) ON DELETE SET NULL,
    runtime                  text CHECK (length(runtime) <= 16),
    project                  text CHECK (length(project) <= 64),
    host                     text CHECK (length(host) <= 64),
    placement                text NOT NULL DEFAULT 'host' CHECK (placement IN ('host', 'sandbox')),
    lease_expires_at         timestamptz,
    created_at               timestamptz NOT NULL DEFAULT now(),
    -- Only service agents receive webhook pings (a2a INV-12).
    CONSTRAINT agents_webhook_service_only CHECK (kind = 'service' OR (webhook_url IS NULL AND webhook_secret IS NULL)),
    CONSTRAINT agents_not_own_parent CHECK (parent_agent_id IS NULL OR parent_agent_id <> id),
    -- The operator row is the admin panel's: no parent, no VM, no webhook.
    CONSTRAINT agents_operator_plain CHECK (
        kind <> 'operator' OR (parent_agent_id IS NULL AND sandbox_id IS NULL AND lease_expires_at IS NULL)
    )
);
-- At most one operator row (a2a B11: a second one broke every chat call).
CREATE UNIQUE INDEX uq_agents_one_operator ON agents ((true)) WHERE kind = 'operator';
CREATE INDEX ix_agents_parent_agent_id ON agents (parent_agent_id);
CREATE INDEX ix_agents_sandbox_id ON agents (sandbox_id);
CREATE INDEX ix_agents_lease ON agents (lease_expires_at)
    WHERE lease_expires_at IS NOT NULL AND NOT disabled;

CREATE TABLE agent_sessions (
    id           uuid PRIMARY KEY,
    agent_id     uuid NOT NULL REFERENCES agents (id),
    name         text NOT NULL CHECK (length(name) BETWEEN 1 AND 160),
    last_seen_at timestamptz NOT NULL,
    closed_at    timestamptz,
    close_reason text CHECK (close_reason IN ('idle', 'closed')),
    created_at   timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_agent_sessions_agent_name UNIQUE (agent_id, name),
    -- Target of the composite foreign keys that tie a session to its agent.
    CONSTRAINT uq_agent_sessions_id_agent UNIQUE (id, agent_id),
    CONSTRAINT agent_sessions_closed CHECK ((closed_at IS NULL) = (close_reason IS NULL))
);
CREATE INDEX ix_agent_sessions_open ON agent_sessions (agent_id, closed_at);
CREATE INDEX ix_agent_sessions_idle ON agent_sessions (last_seen_at) WHERE closed_at IS NULL;

-- ----------------------------------------------------------- requests

CREATE TABLE access_requests (
    id                      uuid PRIMARY KEY,
    agent_id                uuid NOT NULL REFERENCES agents (id),
    session_id              uuid,
    delegation_thread_id    uuid,   -- FK added after a2a_threads
    delegator_agent_id      uuid REFERENCES agents (id),
    platform                text NOT NULL CHECK (platform IN
                            ('github', 'homelab', 'kubernetes', 'a2a', 'google', 'agents',
                             'sandbox', 'hostexec', 'mcp', 'models')),
    resource                text NOT NULL CHECK (length(resource) BETWEEN 1 AND 512),
    -- What the agent asked for, as submitted (before validation narrowed it):
    -- the audit record, and all there is for a request refused before its
    -- capability and scope parsed.
    requested_capability    text NOT NULL CHECK (length(requested_capability) BETWEEN 1 AND 128),
    requested_scope         jsonb NOT NULL CHECK (jsonb_typeof(requested_scope) = 'object'),
    -- The canonical privilege (core::Authority::to_json). NULL only on a
    -- request refused before it parsed.
    authority               jsonb CHECK (authority IS NULL OR jsonb_typeof(authority) = 'object'),
    justification           text NOT NULL,
    requested_duration_secs integer NOT NULL CHECK (requested_duration_secs > 0),
    risk_notes              jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(risk_notes) = 'array'),
    status                  text NOT NULL CHECK (status IN
                            ('pending', 'llm_evaluating', 'llm_denied', 'awaiting_human', 'approved',
                             'provisioning', 'granted', 'provision_failed', 'denied')),
    attempt                 integer NOT NULL DEFAULT 0 CHECK (attempt >= 0),
    decision_source         text CHECK (decision_source IN ('policy', 'rule', 'llm', 'human')),
    decided_by              text CHECK (length(decided_by) <= 128),
    decision_reason         text,
    approved_duration_secs  integer CHECK (approved_duration_secs > 0),
    approved_authority      jsonb CHECK (approved_authority IS NULL OR jsonb_typeof(approved_authority) = 'object'),
    approved_resource       text CHECK (length(approved_resource) BETWEEN 1 AND 512),
    decided_at              timestamptz,
    discord_channel_id      bigint,
    discord_message_id      bigint,
    discord_thread_id       bigint,
    created_at              timestamptz NOT NULL DEFAULT now(),
    updated_at              timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_access_requests_id_agent_platform UNIQUE (id, agent_id, platform),
    CONSTRAINT uq_access_requests_id_agent UNIQUE (id, agent_id),
    CONSTRAINT fk_access_requests_session
        FOREIGN KEY (session_id, agent_id) REFERENCES agent_sessions (id, agent_id),
    -- Delegation: the thread and the delegator come together, never for a2a.
    CONSTRAINT access_requests_delegation_pair
        CHECK ((delegation_thread_id IS NULL) = (delegator_agent_id IS NULL)),
    CONSTRAINT access_requests_a2a_not_delegable
        CHECK (delegation_thread_id IS NULL OR platform <> 'a2a'),
    CONSTRAINT access_requests_delegator_other
        CHECK (delegator_agent_id IS NULL OR delegator_agent_id <> agent_id),
    CONSTRAINT access_requests_authority
        CHECK (authority IS NOT NULL OR status IN ('pending', 'denied')),
    -- A human edit sets the resource and the authority together.
    CONSTRAINT access_requests_approved_pair
        CHECK ((approved_authority IS NULL) = (approved_resource IS NULL)),
    -- Everything at or past APPROVED was approved: by whom, when, for how long.
    CONSTRAINT access_requests_approved_fields CHECK (
        status NOT IN ('approved', 'provisioning', 'granted', 'provision_failed')
        OR (approved_duration_secs IS NOT NULL AND decision_source IS NOT NULL AND decided_at IS NOT NULL)
    ),
    CONSTRAINT access_requests_denied_fields CHECK (
        status <> 'denied' OR (decision_source IS NOT NULL AND decided_at IS NOT NULL)
    ),
    -- LLM states mean at least one evaluation was started.
    CONSTRAINT access_requests_llm_attempt CHECK (
        status NOT IN ('llm_evaluating', 'llm_denied') OR attempt >= 1
    )
);
CREATE INDEX ix_access_requests_agent_id ON access_requests (agent_id, created_at DESC);
CREATE INDEX ix_access_requests_status ON access_requests (status, platform);
CREATE INDEX ix_access_requests_created_at ON access_requests (created_at DESC);
CREATE INDEX ix_access_requests_updated_at ON access_requests (updated_at);
CREATE INDEX ix_access_requests_delegation ON access_requests (delegation_thread_id, created_at)
    WHERE delegation_thread_id IS NOT NULL;
CREATE INDEX ix_access_requests_decisions ON access_requests (decision_source, created_at DESC);

CREATE TABLE llm_evaluations (
    id                      uuid PRIMARY KEY,
    request_id              uuid NOT NULL REFERENCES access_requests (id),
    attempt                 integer NOT NULL CHECK (attempt >= 1),
    model                   text NOT NULL CHECK (length(model) <= 128),
    verdict                 text NOT NULL CHECK (verdict IN ('approve', 'deny')),
    reasoning               text NOT NULL DEFAULT '',
    suggested_duration_secs integer CHECK (suggested_duration_secs > 0),
    raw_response            jsonb NOT NULL DEFAULT '{}',
    created_at              timestamptz NOT NULL DEFAULT now(),
    -- One recorded verdict per evaluation round.
    CONSTRAINT uq_llm_evaluations_attempt UNIQUE (request_id, attempt)
);

-- -------------------------------------------------------------- grants

CREATE TABLE grants (
    id                   uuid PRIMARY KEY,
    request_id           uuid NOT NULL,
    agent_id             uuid NOT NULL REFERENCES agents (id),
    session_id           uuid,
    delegation_thread_id uuid,   -- FK added after a2a_threads
    delegator_agent_id   uuid REFERENCES agents (id),
    platform             text NOT NULL CHECK (platform IN
                         ('github', 'homelab', 'kubernetes', 'a2a', 'google', 'agents',
                          'sandbox', 'hostexec', 'mcp', 'models')),
    resource             text NOT NULL CHECK (length(resource) BETWEEN 1 AND 512),
    authority            jsonb NOT NULL CHECK (jsonb_typeof(authority) = 'object'),
    granted_at           timestamptz NOT NULL,
    expires_at           timestamptz NOT NULL,
    status               text NOT NULL CHECK (status IN
                         ('provisioning', 'active', 'expired', 'revoked', 'provision_failed')),
    provisioner_state    jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(provisioner_state) = 'object'),
    revoked_at           timestamptz,
    revoke_reason        text,
    created_at           timestamptz NOT NULL DEFAULT now(),
    -- At most one grant per request, of the request's own agent and platform.
    CONSTRAINT uq_grants_request_id UNIQUE (request_id),
    CONSTRAINT fk_grants_request
        FOREIGN KEY (request_id, agent_id, platform) REFERENCES access_requests (id, agent_id, platform),
    CONSTRAINT fk_grants_session
        FOREIGN KEY (session_id, agent_id) REFERENCES agent_sessions (id, agent_id),
    CONSTRAINT uq_grants_id_agent UNIQUE (id, agent_id),
    CONSTRAINT grants_delegation_pair
        CHECK ((delegation_thread_id IS NULL) = (delegator_agent_id IS NULL)),
    CONSTRAINT grants_ended CHECK (status NOT IN ('expired', 'revoked') OR revoked_at IS NOT NULL)
);
CREATE INDEX ix_grants_agent_id ON grants (agent_id, granted_at DESC);
CREATE INDEX ix_grants_active_expiry ON grants (status, expires_at);
CREATE INDEX ix_grants_provisioning ON grants (created_at) WHERE status = 'provisioning';
CREATE INDEX ix_grants_platform_resource ON grants (platform, resource, status);
CREATE INDEX ix_grants_delegation ON grants (delegation_thread_id)
    WHERE delegation_thread_id IS NOT NULL;
CREATE INDEX ix_grants_granted_at ON grants (granted_at);
CREATE INDEX ix_grants_revoked_at ON grants (revoked_at) WHERE revoked_at IS NOT NULL;

CREATE TABLE credentials (
    id              uuid PRIMARY KEY,
    grant_id        uuid NOT NULL REFERENCES grants (id),
    kind            text NOT NULL CHECK (length(kind) BETWEEN 1 AND 64),
    value_encrypted text NOT NULL,
    expires_at      timestamptz NOT NULL,
    created_at      timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_credentials_grant_id ON credentials (grant_id, created_at DESC);

-- --------------------------------------------------------------- rules

CREATE TABLE rules (
    id                uuid PRIMARY KEY,
    action            text NOT NULL CHECK (action IN ('auto_approve', 'auto_deny')),
    agent_pattern     text NOT NULL DEFAULT '*' CHECK (length(agent_pattern) BETWEEN 1 AND 128),
    delegator_pattern text CHECK (length(delegator_pattern) BETWEEN 1 AND 128),
    platform          text NOT NULL CHECK (platform IN
                      ('github', 'homelab', 'kubernetes', 'a2a', 'google', 'agents',
                       'sandbox', 'hostexec', 'mcp', 'models')),
    resource_pattern  text NOT NULL DEFAULT '*' CHECK (length(resource_pattern) BETWEEN 1 AND 512),
    -- NULL: any privilege (never pinned, so never clears a sensitive request).
    authority         jsonb CHECK (authority IS NULL OR jsonb_typeof(authority) = 'object'),
    max_duration_secs integer CHECK (max_duration_secs > 0),
    enabled           boolean NOT NULL DEFAULT true,
    created_by        text NOT NULL DEFAULT '' CHECK (length(created_by) <= 128),
    notes             text NOT NULL DEFAULT '',
    expires_at        timestamptz,
    created_at        timestamptz NOT NULL DEFAULT now(),
    -- Tie-break for rules created in the same instant (core B-22): newest first
    -- is ORDER BY created_at DESC, seq DESC.
    seq               bigint GENERATED ALWAYS AS IDENTITY UNIQUE
);
CREATE INDEX ix_rules_live ON rules (platform, created_at DESC, seq DESC) WHERE enabled;
CREATE INDEX ix_rules_created_at ON rules (created_at DESC, seq DESC);

-- ----------------------------------------------------------------- a2a

CREATE TABLE a2a_threads (
    id                   uuid PRIMARY KEY,
    initiator_agent_id   uuid NOT NULL REFERENCES agents (id),
    initiator_session_id uuid,
    responder_agent_id   uuid NOT NULL REFERENCES agents (id),
    responder_session_id uuid,
    topic                text CHECK (length(topic) <= 256 AND topic !~ '[\x01-\x1f\x7f]'),
    -- The initiator's a2a grant; NULL only on the operator's threads.
    grant_id             uuid,
    state                text NOT NULL CHECK (state IN ('pending_open', 'open', 'closed')),
    accepted_at          timestamptz,
    closed_at            timestamptz,
    last_activity_at     timestamptz NOT NULL,
    last_seq             integer NOT NULL CHECK (last_seq >= 0),
    closed_by            uuid REFERENCES agents (id),
    close_reason         text CHECK (close_reason IN
                         ('rejected', 'closed', 'open_timeout', 'idle_timeout', 'peer_gone', 'grant_revoked')),
    close_note           text,
    created_at           timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT fk_a2a_threads_initiator_session
        FOREIGN KEY (initiator_session_id, initiator_agent_id) REFERENCES agent_sessions (id, agent_id),
    CONSTRAINT fk_a2a_threads_responder_session
        FOREIGN KEY (responder_session_id, responder_agent_id) REFERENCES agent_sessions (id, agent_id),
    -- The backing grant is the initiator's own.
    CONSTRAINT fk_a2a_threads_grant
        FOREIGN KEY (grant_id, initiator_agent_id) REFERENCES grants (id, agent_id),
    CONSTRAINT a2a_threads_two_parties CHECK (initiator_agent_id <> responder_agent_id),
    CONSTRAINT a2a_threads_closed CHECK (
        (state = 'closed') = (closed_at IS NOT NULL AND close_reason IS NOT NULL)
    ),
    CONSTRAINT a2a_threads_accepted CHECK (state <> 'open' OR accepted_at IS NOT NULL),
    CONSTRAINT a2a_threads_closer CHECK (
        closed_by IS NULL OR closed_by = initiator_agent_id OR closed_by = responder_agent_id
    )
);
CREATE INDEX ix_a2a_threads_initiator ON a2a_threads (initiator_agent_id, last_activity_at);
CREATE INDEX ix_a2a_threads_responder ON a2a_threads (responder_agent_id, last_activity_at);
CREATE INDEX ix_a2a_threads_state ON a2a_threads (state, last_activity_at);
CREATE INDEX ix_a2a_threads_pending ON a2a_threads (created_at) WHERE state = 'pending_open';
CREATE INDEX ix_a2a_threads_initiator_session ON a2a_threads (initiator_session_id)
    WHERE initiator_session_id IS NOT NULL;
CREATE INDEX ix_a2a_threads_responder_session ON a2a_threads (responder_session_id)
    WHERE responder_session_id IS NOT NULL;
CREATE INDEX ix_a2a_threads_grant ON a2a_threads (grant_id) WHERE grant_id IS NOT NULL;
CREATE INDEX ix_a2a_threads_last_activity ON a2a_threads (last_activity_at);
CREATE INDEX ix_a2a_threads_created_at ON a2a_threads (created_at);
CREATE INDEX ix_a2a_threads_closed_at ON a2a_threads (closed_at) WHERE closed_at IS NOT NULL;

ALTER TABLE access_requests ADD CONSTRAINT fk_access_requests_delegation_thread
    FOREIGN KEY (delegation_thread_id) REFERENCES a2a_threads (id);
ALTER TABLE grants ADD CONSTRAINT fk_grants_delegation_thread
    FOREIGN KEY (delegation_thread_id) REFERENCES a2a_threads (id);

CREATE TABLE a2a_messages (
    id                 uuid PRIMARY KEY,
    thread_id          uuid NOT NULL REFERENCES a2a_threads (id),
    seq                integer NOT NULL CHECK (seq >= 1),
    sender_agent_id    uuid NOT NULL REFERENCES agents (id),
    sender_session_id  uuid,
    recipient_agent_id uuid NOT NULL REFERENCES agents (id),
    grant_id           uuid REFERENCES grants (id),
    -- json, not jsonb: the payload comes back exactly as it was sent.
    payload            json NOT NULL CHECK (json_typeof(payload) = 'object'),
    created_at         timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT fk_a2a_messages_sender_session
        FOREIGN KEY (sender_session_id, sender_agent_id) REFERENCES agent_sessions (id, agent_id),
    CONSTRAINT a2a_messages_two_parties CHECK (sender_agent_id <> recipient_agent_id)
);
CREATE UNIQUE INDEX ix_a2a_messages_thread_seq ON a2a_messages (thread_id, seq);
CREATE INDEX ix_a2a_messages_sender ON a2a_messages (sender_agent_id);
CREATE INDEX ix_a2a_messages_recipient ON a2a_messages (recipient_agent_id);

-- --------------------------------------------------------- containment

-- One row per entry (the Python kept a JSON list in broker_flags, a
-- lost-update hazard: core B-8). Order = `position` (the first matching
-- entry is the one reported).
CREATE TABLE containment_entries (
    id         text PRIMARY KEY CHECK (id ~ '^[0-9a-f]{8}$'),
    match      jsonb NOT NULL CHECK (jsonb_typeof(match) = 'object'),
    reason     text NOT NULL CHECK (length(reason) <= 500),
    evidence   text NOT NULL DEFAULT '' CHECK (length(evidence) <= 4000),
    created_by text NOT NULL,
    source     text NOT NULL CHECK (source IN ('operator', 'agent', 'lockdown', '')),
    at         timestamptz NOT NULL,
    position   bigint GENERATED ALWAYS AS IDENTITY UNIQUE
);

CREATE TABLE broker_flags (
    key        text PRIMARY KEY CHECK (length(key) BETWEEN 1 AND 64),
    value      jsonb NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- ------------------------------------------------------------ sandboxes

CREATE TABLE pending_key_deliveries (
    id            uuid PRIMARY KEY,
    -- At most one pending key per agent.
    agent_id      uuid NOT NULL UNIQUE REFERENCES agents (id),
    sandbox_id    uuid NOT NULL REFERENCES daemons (id) ON DELETE CASCADE,
    -- Which key this is, so an ack for an older key deletes nothing (sandboxd B-6).
    key_id        text NOT NULL CHECK (length(key_id) BETWEEN 1 AND 16),
    key_encrypted text NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_pending_key_deliveries_sandbox_id ON pending_key_deliveries (sandbox_id);

-- ------------------------------------------------------------- hostexec

CREATE TABLE host_jobs (
    id            uuid PRIMARY KEY,
    grant_id      uuid REFERENCES grants (id),
    request_id    uuid NOT NULL,
    agent_id      uuid NOT NULL REFERENCES agents (id),
    host          text NOT NULL CHECK (length(host) BETWEEN 1 AND 128),
    tier          text NOT NULL CHECK (tier IN ('user', 'root')),
    -- A shell's id (its request's id) for a shell command; NULL for run/tpl.
    shell_id      uuid,
    spec          jsonb NOT NULL CHECK (jsonb_typeof(spec) = 'object'),
    status        text NOT NULL CHECK (status IN ('starting', 'running', 'done', 'refused', 'lost')),
    via           text CHECK (length(via) <= 32),
    exit_code     integer,
    error         text,
    output        text,
    output_bytes  integer CHECK (output_bytes >= 0),
    output_sha256 text CHECK (output_sha256 ~ '^[0-9a-f]{64}$'),
    truncated     boolean NOT NULL DEFAULT false,
    duration_ms   bigint CHECK (duration_ms >= 0),
    finished_at   timestamptz,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT fk_host_jobs_request
        FOREIGN KEY (request_id, agent_id) REFERENCES access_requests (id, agent_id),
    CONSTRAINT fk_host_jobs_grant
        FOREIGN KEY (grant_id, agent_id) REFERENCES grants (id, agent_id),
    CONSTRAINT host_jobs_done CHECK (status <> 'done' OR finished_at IS NOT NULL)
);
CREATE INDEX ix_host_jobs_grant_id ON host_jobs (grant_id);
CREATE INDEX ix_host_jobs_request_id ON host_jobs (request_id);
CREATE INDEX ix_host_jobs_agent_id ON host_jobs (agent_id);
CREATE INDEX ix_host_jobs_shell_id ON host_jobs (shell_id, created_at) WHERE shell_id IS NOT NULL;
CREATE INDEX ix_host_jobs_status ON host_jobs (status);
CREATE INDEX ix_host_jobs_host ON host_jobs (host, created_at DESC);
CREATE INDEX ix_host_jobs_created_at ON host_jobs (created_at DESC);
CREATE INDEX ix_host_jobs_finished_at ON host_jobs (finished_at) WHERE finished_at IS NOT NULL;

-- ---------------------------------------------------------------- oauth

CREATE TABLE oauth_clients (
    id            text PRIMARY KEY CHECK (id ~ '^[A-Za-z0-9_-]{1,64}$'),
    name          text NOT NULL DEFAULT '' CHECK (length(name) <= 200),
    -- Validated by the registration code (https, allowed hosts, length).
    redirect_uris jsonb NOT NULL CHECK (jsonb_typeof(redirect_uris) = 'array'),
    secret_hash   text CHECK (secret_hash ~ '^[0-9a-f]{64}$'),
    agent_id      uuid REFERENCES agents (id),
    last_used_at  timestamptz,
    revoked_at    timestamptz,
    created_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX ix_oauth_clients_agent_id ON oauth_clients (agent_id);
CREATE INDEX ix_oauth_clients_live ON oauth_clients (created_at) WHERE revoked_at IS NULL;

CREATE TABLE oauth_tokens (
    id             uuid PRIMARY KEY,
    kind           text NOT NULL CHECK (kind IN ('code', 'access', 'refresh')),
    token_hash     text NOT NULL UNIQUE CHECK (token_hash ~ '^[0-9a-f]{64}$'),
    client_id      text NOT NULL REFERENCES oauth_clients (id),
    agent_id       uuid NOT NULL REFERENCES agents (id),
    family         uuid NOT NULL,
    expires_at     timestamptz NOT NULL,
    used_at        timestamptz,
    revoked_at     timestamptz,
    code_challenge text CHECK (code_challenge ~ '^[A-Za-z0-9_-]{43,128}$'),
    redirect_uri   text,
    authorized_by  text NOT NULL DEFAULT '' CHECK (length(authorized_by) <= 128),
    created_at     timestamptz NOT NULL DEFAULT now(),
    -- A code carries its PKCE challenge and redirect; tokens carry neither.
    CONSTRAINT oauth_tokens_code_fields CHECK (
        (kind = 'code') = (code_challenge IS NOT NULL AND redirect_uri IS NOT NULL)
    ),
    -- Access tokens are presented, never consumed.
    CONSTRAINT oauth_tokens_access_unused CHECK (kind <> 'access' OR used_at IS NULL)
);
CREATE INDEX ix_oauth_tokens_client_id ON oauth_tokens (client_id, kind);
CREATE INDEX ix_oauth_tokens_agent_id ON oauth_tokens (agent_id);
CREATE INDEX ix_oauth_tokens_family ON oauth_tokens (family);
CREATE INDEX ix_oauth_tokens_expires_at ON oauth_tokens (expires_at);

-- ------------------------------------------------------------- triggers
-- Status machines, enforced on every UPDATE (and the initial status on INSERT).

CREATE FUNCTION access_requests_status_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'pending' THEN
            RAISE EXCEPTION 'access request inserted as %, not pending', NEW.status
                USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id <> OLD.id OR NEW.agent_id <> OLD.agent_id OR NEW.platform <> OLD.platform
       OR NEW.created_at <> OLD.created_at
       OR NEW.delegation_thread_id IS DISTINCT FROM OLD.delegation_thread_id
       OR NEW.delegator_agent_id IS DISTINCT FROM OLD.delegator_agent_id
       OR NEW.session_id IS DISTINCT FROM OLD.session_id THEN
        RAISE EXCEPTION 'access request identity columns are immutable'
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.attempt < OLD.attempt THEN
        RAISE EXCEPTION 'access request attempt went backwards'
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
        (OLD.status = 'pending' AND NEW.status IN ('denied', 'approved', 'llm_evaluating', 'awaiting_human')) OR
        (OLD.status = 'llm_evaluating' AND NEW.status IN ('approved', 'llm_denied', 'awaiting_human')) OR
        (OLD.status = 'llm_denied' AND NEW.status IN ('llm_evaluating', 'awaiting_human')) OR
        (OLD.status = 'awaiting_human' AND NEW.status IN ('approved', 'denied')) OR
        (OLD.status = 'approved' AND NEW.status = 'provisioning') OR
        (OLD.status = 'provisioning' AND NEW.status IN ('granted', 'provision_failed'))
    ) THEN
        RAISE EXCEPTION 'access request status % -> % is not allowed', OLD.status, NEW.status
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;

CREATE TRIGGER access_requests_status_guard
    BEFORE INSERT OR UPDATE ON access_requests
    FOR EACH ROW EXECUTE FUNCTION access_requests_status_guard();

CREATE FUNCTION grants_status_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'provisioning' THEN
            RAISE EXCEPTION 'grant inserted as %, not provisioning', NEW.status
                USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END IF;
    IF NEW.id <> OLD.id OR NEW.request_id <> OLD.request_id OR NEW.agent_id <> OLD.agent_id
       OR NEW.platform <> OLD.platform OR NEW.authority <> OLD.authority
       OR NEW.delegation_thread_id IS DISTINCT FROM OLD.delegation_thread_id THEN
        RAISE EXCEPTION 'grant identity columns are immutable'
            USING ERRCODE = 'check_violation';
    END IF;
    -- An ended grant never extends; an active one may only be shortened
    -- (containment and disable "revoke later" by setting expires_at = now).
    IF NEW.expires_at > OLD.expires_at THEN
        RAISE EXCEPTION 'grant expiry may only move earlier'
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
        (OLD.status = 'provisioning' AND NEW.status IN ('active', 'provision_failed')) OR
        (OLD.status = 'active' AND NEW.status IN ('expired', 'revoked'))
    ) THEN
        RAISE EXCEPTION 'grant status % -> % is not allowed', OLD.status, NEW.status
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;

CREATE TRIGGER grants_status_guard
    BEFORE INSERT OR UPDATE ON grants
    FOR EACH ROW EXECUTE FUNCTION grants_status_guard();

CREATE FUNCTION a2a_threads_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF NEW.initiator_agent_id <> OLD.initiator_agent_id
       OR NEW.responder_agent_id <> OLD.responder_agent_id
       OR NEW.initiator_session_id IS DISTINCT FROM OLD.initiator_session_id
       OR NEW.grant_id IS DISTINCT FROM OLD.grant_id THEN
        RAISE EXCEPTION 'a2a thread parties are immutable'
            USING ERRCODE = 'check_violation';
    END IF;
    -- A responder binding, once made, is never cleared or moved (a2a INV-2).
    IF OLD.responder_session_id IS NOT NULL
       AND NEW.responder_session_id IS DISTINCT FROM OLD.responder_session_id THEN
        RAISE EXCEPTION 'a2a thread responder session is already bound'
            USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.last_seq < OLD.last_seq THEN
        RAISE EXCEPTION 'a2a thread last_seq went backwards'
            USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.state = 'closed' AND (NEW.state <> 'closed' OR NEW.last_seq <> OLD.last_seq) THEN
        RAISE EXCEPTION 'a2a thread is closed'
            USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.state = 'open' AND NEW.state = 'pending_open' THEN
        RAISE EXCEPTION 'a2a thread cannot go back to pending_open'
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;

CREATE TRIGGER a2a_threads_guard
    BEFORE UPDATE ON a2a_threads
    FOR EACH ROW EXECUTE FUNCTION a2a_threads_guard();

-- No message lands on a closed thread, and seq is the thread's counter
-- (a2a INV-7, INV-9). The insert must come after the thread's last_seq bump
-- in the same transaction.
CREATE FUNCTION a2a_messages_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
    t record;
BEGIN
    SELECT state, last_seq INTO t FROM a2a_threads WHERE id = NEW.thread_id;
    IF t.state = 'closed' THEN
        RAISE EXCEPTION 'a2a thread is closed' USING ERRCODE = 'check_violation';
    END IF;
    IF NEW.seq <> t.last_seq THEN
        RAISE EXCEPTION 'a2a message seq % is not the thread''s last_seq %', NEW.seq, t.last_seq
            USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;

CREATE TRIGGER a2a_messages_guard
    BEFORE INSERT ON a2a_messages
    FOR EACH ROW EXECUTE FUNCTION a2a_messages_guard();

CREATE FUNCTION host_jobs_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        IF NEW.status <> 'starting' THEN
            RAISE EXCEPTION 'host job inserted as %, not starting', NEW.status
                USING ERRCODE = 'check_violation';
        END IF;
        RETURN NEW;
    END IF;
    -- A stored result is never overwritten (hostexec INV-32).
    IF NEW.status IS DISTINCT FROM OLD.status AND NOT (
        (OLD.status = 'starting' AND NEW.status IN ('running', 'done', 'refused', 'lost')) OR
        (OLD.status = 'running' AND NEW.status IN ('done', 'refused', 'lost'))
    ) THEN
        RAISE EXCEPTION 'host job status % -> % is not allowed', OLD.status, NEW.status
            USING ERRCODE = 'check_violation';
    END IF;
    IF OLD.status IN ('done', 'refused', 'lost') AND (
        NEW.output IS DISTINCT FROM OLD.output OR NEW.exit_code IS DISTINCT FROM OLD.exit_code
        OR NEW.error IS DISTINCT FROM OLD.error OR NEW.output_sha256 IS DISTINCT FROM OLD.output_sha256
    ) THEN
        RAISE EXCEPTION 'host job result is final' USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END $$;

CREATE TRIGGER host_jobs_guard
    BEFORE INSERT OR UPDATE ON host_jobs
    FOR EACH ROW EXECUTE FUNCTION host_jobs_guard();
